class Identity(nn.Module):
    def __init__(self):
        super(Identity, self).__init__()
    def forward(self, x):
        return x

class MLP(nn.Module):
    def __init__(self, n_inputs, n_outputs, hparams):
        super(MLP, self).__init__()
        self.input = nn.Linear(n_inputs, hparams['mlp_width'])
        self.dropout = nn.Dropout(hparams['mlp_dropout'])
        self.hiddens = nn.ModuleList([
            nn.Linear(hparams['mlp_width'], hparams['mlp_width'])
            for _ in range(hparams['mlp_depth']-2)])
        self.output = nn.Linear(hparams['mlp_width'], n_outputs)
        self.n_outputs = n_outputs
        self.activation = nn.Identity()
    def forward(self, x):
        x = self.input(x)
        x = self.dropout(x)
        x = F.relu(x)
        for hidden in self.hiddens:
            x = hidden(x)
            x = self.dropout(x)
            x = F.relu(x)
        x = self.output(x)
        x = self.activation(x)
        return x

class ResNet(torch.nn.Module):
    def __init__(self, input_shape, hparams):
        super(ResNet, self).__init__()
        if hparams['resnet18']:
            self.network = torchvision.models.resnet18(pretrained=True)
            self.n_outputs = 512
        else:
            self.network = torchvision.models.resnet50(pretrained=True)
            self.n_outputs = 2048
        if hparams['resnet50_augmix']:
            self.network = timm.create_model('resnet50.ram_in1k', pretrained=True)
            self.n_outputs = 2048
        nc = input_shape[0]
        if nc != 3:
            tmp = self.network.conv1.weight.data.clone()
            self.network.conv1 = nn.Conv2d(
                nc, 64, kernel_size=(7, 7), stride=(2, 2), padding=(3, 3), bias=False)
            for i in range(nc):
                self.network.conv1.weight.data[:, i, :, :] = tmp[:, i % 3, :, :]
        del self.network.fc
        self.network.fc = Identity()
        if hparams["freeze_bn"]:
            self.freeze_bn()
        self.hparams = hparams
        self.dropout = nn.Dropout(hparams['resnet_dropout'])
        self.activation = nn.Identity()
    def forward(self, x):
        return self.activation(self.dropout(self.network(x)))
    def train(self, mode=True):
        super().train(mode)
        if self.hparams["freeze_bn"]:
            self.freeze_bn()
    def freeze_bn(self):
        for m in self.network.modules():
            if isinstance(m, nn.BatchNorm2d):
                m.eval()

class MNIST_CNN(nn.Module):
    n_outputs = 128
    def __init__(self, input_shape):
        super(MNIST_CNN, self).__init__()
        self.conv1 = nn.Conv2d(input_shape[0], 64, 3, 1, padding=1)
        self.conv2 = nn.Conv2d(64, 128, 3, stride=2, padding=1)
        self.conv3 = nn.Conv2d(128, 128, 3, 1, padding=1)
        self.conv4 = nn.Conv2d(128, 128, 3, 1, padding=1)
        self.bn0 = nn.GroupNorm(8, 64)
        self.bn1 = nn.GroupNorm(8, 128)
        self.bn2 = nn.GroupNorm(8, 128)
        self.bn3 = nn.GroupNorm(8, 128)
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.activation = nn.Identity()
    def forward(self, x):
        x = self.conv1(x)
        x = F.relu(x)
        x = self.bn0(x)
        x = self.conv2(x)
        x = F.relu(x)
        x = self.bn1(x)
        x = self.conv3(x)
        x = F.relu(x)
        x = self.bn2(x)
        x = self.conv4(x)
        x = F.relu(x)
        x = self.bn3(x)
        x = self.avgpool(x)
        x = x.view(len(x), -1)
        return self.activation(x)

def Featurizer(input_shape, hparams):
    if input_shape[1:3] == (28, 28):
        return MNIST_CNN(input_shape)
    elif input_shape[1:3] == (224, 224):
        return ResNet(input_shape, hparams)
    else:
        raise NotImplementedError("Featurizer for this input shape not covered by the problem description.")

def Classifier(in_features, out_features, is_nonlinear=False):
    if is_nonlinear:
        raise NotImplementedError("Non-linear classifier not covered by the problem description")
    else:
        return torch.nn.Linear(in_features, out_features)

def random_pairs_of_minibatches(minibatches):
    perm = torch.randperm(len(minibatches)).tolist()
    pairs = []
    for i in range(len(minibatches)):
        j = i + 1 if i < (len(minibatches) - 1) else 0
        xi, yi = minibatches[perm[i]][0], minibatches[perm[i]][1]
        xj, yj = minibatches[perm[j]][0], minibatches[perm[j]][1]
        min_n = min(len(xi), len(xj))
        pairs.append(((xi[:min_n], yi[:min_n]), (xj[:min_n], yj[:min_n])))
    return pairs

def split_meta_train_test(minibatches, num_meta_test=1):
    n_domains = len(minibatches)
    perm = torch.randperm(n_domains).tolist()
    pairs = []
    meta_train = perm[:(n_domains-num_meta_test)]
    meta_test = perm[-num_meta_test:]
    for i,j in zip(meta_train, cycle(meta_test)):
         xi, yi = minibatches[i][0], minibatches[i][1]
         xj, yj = minibatches[j][0], minibatches[j][1]
         min_n = min(len(xi), len(xj))
         pairs.append(((xi[:min_n], yi[:min_n]), (xj[:min_n], yj[:min_n])))
    return pairs

def make_selector_fn(selector):
    if isinstance(selector, str):
        if ',' in selector:
            parts = selector.split(',')
            part_selectors = [make_selector_fn(part) for part in parts]
            return lambda obj: tuple(sel(obj) for sel in part_selectors)
        elif '.' in selector:
            parts = selector.split('.')
            part_selectors = [make_selector_fn(part) for part in parts]
            def f(obj):
                for sel in part_selectors:
                    obj = sel(obj)
                return obj
            return f
        else:
            key = selector.strip()
            return lambda obj: obj[key]
    elif isinstance(selector, types.FunctionType):
        return selector
    else:
        raise TypeError

def hashable(obj):
    try:
        hash(obj)
        return obj
    except TypeError:
        return json.dumps({'_':obj}, sort_keys=True)

class Q(object):
    def __init__(self, list_):
        super(Q, self).__init__()
        self._list = list_
    def __len__(self):
        return len(self._list)
    def __getitem__(self, key):
        return self._list[key]
    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self._list == other._list
        else:
            return self._list == other
    def __str__(self):
        return str(self._list)
    def __repr__(self):
        return repr(self._list)
    def _append(self, item):
        self._list.append(item)
    def group(self, selector):
        selector = make_selector_fn(selector)
        groups = {}
        for x in self._list:
            group = selector(x)
            group_key = hashable(group)
            if group_key not in groups:
                groups[group_key] = (group, Q([]))
            groups[group_key][1]._append(x)
        results = [groups[key] for key in sorted(groups.keys())]
        return Q(results)
    def group_map(self, selector, fn):
        return self.group(selector).map(fn)
    def map(self, fn):
        if len(inspect.signature(fn).parameters) > 1:
            return Q([fn(*x) for x in self._list])
        else:
            return Q([fn(x) for x in self._list])
    def select(self, selector):
        selector = make_selector_fn(selector)
        return Q([selector(x) for x in self._list])
    def min(self):
        return min(self._list)
    def max(self):
        return max(self._list)
    def sum(self):
        return sum(self._list)
    def len(self):
        return len(self._list)
    def mean(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            return float(np.mean(self._list))
    def std(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            return float(np.std(self._list))
    def mean_std(self):
        return (self.mean(), self.std())
    def argmax(self, selector):
        selector = make_selector_fn(selector)
        return max(self._list, key=selector)
    def filter(self, fn):
        return Q([x for x in self._list if fn(x)])
    def filter_equals(self, selector, value):
        selector = make_selector_fn(selector)
        return self.filter(lambda r: selector(r) == value)
    def filter_not_none(self):
        return self.filter(lambda r: r is not None)
    def filter_not_nan(self):
        return self.filter(lambda r: not np.isnan(r))
    def flatten(self):
        return Q([y for x in self._list for y in x])
    def unique(self):
        result = []
        result_set = set()
        for x in self._list:
            hashable_x = hashable(x)
            if hashable_x not in result_set:
                result_set.add(hashable_x)
                result.append(x)
        return Q(result)
    def sorted(self, key=None):
        if key is None:
            key = lambda x: x
        def key2(x):
            x = key(x)
            if isinstance(x, (np.floating, float)) and np.isnan(x):
                return float('-inf')
            else:
                return x
        return Q(sorted(self._list, key=key2))

class SelectionMethod:
    def __init__(self):
        raise TypeError
    @classmethod
    def run_acc(self, run_records):
        raise NotImplementedError
    @classmethod
    def hparams_accs(self, records):
        return (records.group('args.hparams_seed')
            .map(lambda _, run_records:
                (self.run_acc(run_records), run_records)
            ).filter(lambda x: x[0] is not None)
            .sorted(key=lambda x: x[0]['val_acc'])[::-1]
        )
    @classmethod
    def sweep_acc(self, records):
        _hparams_accs = self.hparams_accs(records)
        if len(_hparams_accs):
            return _hparams_accs[0][0]['test_acc']
        else:
            return None

def get_test_records(records):
    return records.filter(lambda r: len(r['args']['test_envs']) == 1)

class OracleSelectionMethod(SelectionMethod):
    name = "test-domain validation set (oracle)"
    @classmethod
    def run_acc(self, run_records):
        run_records = run_records.filter(lambda r: len(r['args']['test_envs']) == 1)
        if not len(run_records):
            return None
        test_env = run_records[0]['args']['test_envs'][0]
        test_out_acc_key = 'env{}_out_acc'.format(test_env)
        test_in_acc_key = 'env{}_in_acc'.format(test_env)
        chosen_record = run_records.sorted(lambda r: r['step'])[-1]
        return {
            'val_acc':  chosen_record[test_out_acc_key],
            'test_acc': chosen_record[test_in_acc_key]
        }

class IIDAccuracySelectionMethod(SelectionMethod):
    name = "training-domain validation set"
    @classmethod
    def _step_acc(self, record):
        test_env = record['args']['test_envs'][0]
        val_env_keys = []
        for i in itertools.count():
            if f'env{i}_out_acc' not in record:
                break
            if i != test_env:
                val_env_keys.append(f'env{i}_out_acc')
        test_in_acc_key = 'env{}_in_acc'.format(test_env)
        return {
            'val_acc': np.mean([record[key] for key in val_env_keys]),
            'test_acc': record[test_in_acc_key]
        }
    @classmethod
    def run_acc(self, run_records):
        test_records = get_test_records(run_records)
        if not len(test_records):
            return None
        return test_records.map(self._step_acc).argmax('val_acc')

class LeaveOneOutSelectionMethod(SelectionMethod):
    name = "leave-one-domain-out cross-validation"
    @classmethod
    def _step_acc(self, records):
        test_records = get_test_records(records)
        if len(test_records) != 1:
            return None
        test_env = test_records[0]['args']['test_envs'][0]
        n_envs = 0
        for i in itertools.count():
            if f'env{i}_out_acc' not in records[0]:
                break
            n_envs += 1
        val_accs = np.zeros(n_envs) - 1
        for r in records.filter(lambda r: len(r['args']['test_envs']) == 2):
            val_env = (set(r['args']['test_envs']) - set([test_env])).pop()
            val_accs[val_env] = r['env{}_in_acc'.format(val_env)]
        val_accs = list(val_accs[:test_env]) + list(val_accs[test_env+1:])
        if any([v==-1 for v in val_accs]):
            return None
        val_acc = np.sum(val_accs) / (n_envs-1)
        return {
            'val_acc': val_acc,
            'test_acc': test_records[0]['env{}_in_acc'.format(test_env)]
        }
    @classmethod
    def run_acc(self, records):
        step_accs = records.group('step').map(lambda step, step_records:
            self._step_acc(step_records)
        ).filter_not_none()
        if len(step_accs):
            return step_accs.argmax('val_acc')
        else:
            return None

import numpy as np
import torch
from torch import nn
from typing import List, Union
from typing_extensions import Literal
from scipy.stats import ortho_group
import os
import cooper

use_cuda = torch.cuda.is_available()
device = "cuda" if use_cuda else "cpu"

def get_mlp(n_in: int, n_out: int,
            layers: List[int],
            layer_normalization: Union[None, Literal["bn"], Literal["gn"]] = None,
            output_normalization: Union[None, Literal["bn"], Literal["gn"]] = None,
            output_normalization_kwargs=None, act_inf_param=0.02, linear=False):
    modules: List[nn.Module] = []

    def add_module(n_layer_in: int, n_layer_out: int, last_layer: bool = False, mid_layer: bool = False):
        modules.append(nn.Linear(n_layer_in, n_layer_out))
        if not last_layer:
            if layer_normalization == "bn":
                modules.append(nn.BatchNorm1d(n_layer_out))
            elif layer_normalization == "gn":
                modules.append(nn.GroupNorm(1, n_layer_out))
            if not linear:
               modules.append(nn.LeakyReLU(negative_slope=act_inf_param))
        else:
            if output_normalization == "bn":
                modules.append(nn.BatchNorm1d(n_layer_out))
            elif output_normalization == "gn":
                modules.append(nn.GroupNorm(1, n_layer_out)) 
        return n_layer_out

    if len(layers) > 0:
        n_out_last_layer = n_in
    else:
        assert n_in == n_out, "Network with no layers must have matching n_in and n_out"
        class Lambda(nn.Module):
            def __init__(self, func):
                super().__init__()
                self.func = func
            def forward(self, x):
                return self.func(x)
        modules.append(Lambda(lambda x: x))

    layers.append(n_out)

    for i, l in enumerate(layers):
        n_out_last_layer = add_module(n_out_last_layer, l, i == len(layers)-1)

    if output_normalization_kwargs is None:
        output_normalization_kwargs = {}
    return nn.Sequential(*modules)


def construct_invertible_mlp(n: int = 20, n_layers: int = 2, n_iter_cond_thresh: int = 10000,
                             cond_thresh_ratio: float = 0.25,
                             weight_matrix_init: Union[Literal["pcl"], Literal["rvs"]] = 'pcl',
                             act_fct: Union[Literal["relu"], Literal["leaky_relu"], Literal["elu"],
                                            Literal["smooth_leaky_relu"], Literal["softplus"]] = 'leaky_relu'
                             ):
    class SmoothLeakyReLU(nn.Module):
        def __init__(self, alpha=0.2):
            super().__init__()
            self.alpha = alpha

        def forward(self, x):
            return self.alpha * x + (1 - self.alpha) * torch.log(1 + torch.exp(x))

    def get_act_fct_local(act_fct):
        if act_fct == 'relu':
            return torch.nn.ReLU, {}, 1
        if act_fct == 'leaky_relu':
            return torch.nn.LeakyReLU, {'negative_slope': 0.2}, 1
        elif act_fct == 'elu':
            return torch.nn.ELU, {'alpha': 1.0}, 1
        elif act_fct == 'max_out':
            raise NotImplemented()
        elif act_fct == 'smooth_leaky_relu':
            return SmoothLeakyReLU, {'alpha': 0.2}, 1
        elif act_fct == 'softplus':
            return torch.nn.Softplus, {'beta': 1}, 1
        else:
            raise Exception(f'activation function {act_fct} not defined.')

    layers = []
    act_fct_class, act_kwargs, act_fac = get_act_fct_local(act_fct)

    def l2_normalize(Amat, axis=0):
        l2norm = np.sqrt(np.sum(Amat * Amat, axis))
        Amat = Amat / l2norm
        return Amat

    condList = np.zeros([n_iter_cond_thresh])
    if weight_matrix_init == 'pcl':
        for i in range(n_iter_cond_thresh):
            A = np.random.uniform(-1, 1, [n, n])
            A = l2_normalize(A, axis=0)
            condList[i] = np.linalg.cond(A)
        condList.sort()
    condThresh = condList[int(n_iter_cond_thresh * cond_thresh_ratio)]

    for i in range(n_layers):

        lin_layer = nn.Linear(n, n, bias=False)

        if weight_matrix_init == 'pcl':
            condA = condThresh + 1
            while condA > condThresh:
                weight_matrix = np.random.uniform(-1, 1, (n, n))
                weight_matrix = l2_normalize(weight_matrix, axis=0)

                condA = np.linalg.cond(weight_matrix)
            lin_layer.weight.data = torch.tensor(weight_matrix, dtype=torch.float32)

        elif weight_matrix_init == 'rvs':
            weight_matrix = ortho_group.rvs(n)
            lin_layer.weight.data = torch.tensor(weight_matrix, dtype=torch.float32)
        elif weight_matrix_init == 'expand':
            pass
        else:
            raise Exception(f'weight matrix {weight_matrix_init} not implemented')

        layers.append(lin_layer)

        if i < n_layers - 1:
            layers.append(act_fct_class(**act_kwargs))

    mixing_net = nn.Sequential(*layers)

    for p in mixing_net.parameters():
        p.requires_grad = False

    return mixing_net


def get_decoder(x_dim, z_dim, seed, n_layers, load_f, save_dir, manifold='nn', smooth=False):
    rng_data_gen=np.random.default_rng(seed)
    if manifold == "nn":
        h_dim = x_dim
        neg_slope = 0.2

        if load_f is not None:
            dd = np.load(load_f)
            W0 = [dd[f_key] for f_key in dd]
        else:
            W0 = []
            for l in range(n_layers):
                Wi = rng_data_gen.normal(size=(h_dim, x_dim))
                Wi = np.linalg.qr(Wi.T)[0].T
                Wi *= np.sqrt(2 / (1 + neg_slope ** 2)) * np.sqrt(2. / (x_dim + h_dim))
                W0.append(Wi)

            save_path = os.path.join(save_dir, 'f.npz')
            np.savez(save_path,*W0)

        W=[]
        for l in range(n_layers):
            Wi = W0[l]
            Wi = torch.Tensor(Wi).to(device)
            W.append(Wi)


        def decoder(z_input):
            with torch.no_grad():
                z_input = torch.Tensor(z_input).to(device)
                h = torch.matmul(z_input, W[0])
                if n_layers>1:
                    for l in range(n_layers-1):
                        if smooth:
                            h = neg_slope * h + (1 - neg_slope) * torch.log(1 + torch.exp(h))
                        else:
                            h = torch.maximum(neg_slope * h, h) 
                        h = torch.matmul(h, W[l+1])

            return h
    else:
        raise NotImplementedError(f"The manifold {manifold} is not implemented.")

    return decoder


class Constrained_DE(cooper.ConstrainedMinimizationProblem):
    def __init__(self, latent_dim, n_classes, args_config):
        self.criterion = nn.MSELoss(reduction='sum')
        self.args = args_config
        super().__init__(is_constrained=True)

    def compute_loss(self, x, x_hat, mu, masks, device):
        mini_batch = self.args.batch_size // len(masks)
        log_p_x_given_z = self.criterion(x_hat, x)
        stat_loss = 0
        if self.args.oracle=='oracle':
            log_var_prior = torch.tensor(masks).to(device)
            log_var_prior[log_var_prior==0]=-10

        mu_prior = torch.ones(self.args.nn).to(device)*2

        for k in range(len(masks)):
            if k==len(masks)-1:
                mu_k = mu[k*mini_batch:,:]
            else:
                mu_k=mu[k*mini_batch:(k+1)*mini_batch,:]

            diffs = mu_k - mu_prior
            if self.args.oracle=='oracle':
                std = (log_var_prior[k,:]/2).exp()
            else:
                var = torch.mean(torch.pow(diffs, 2.0))
                std = torch.pow(var, 0.5)
            zscores = diffs / (std+1e-9)
            skews = torch.mean(torch.pow(zscores, 3.0),dim=0)
            kurtoses = torch.mean(torch.pow(zscores, 4.0),dim=0) - 3.0

            stat_loss += torch.mean(torch.abs(skews))+torch.mean(torch.abs(kurtoses))

        return log_p_x_given_z,stat_loss

    def closure(self, inputs, f_mix, g_enc, f_dec, scale_val, masks, device):
        x = f_mix(inputs)
        x = x*scale_val
        z_mu = g_enc(x)
        z_hat = z_mu
        x_hat = f_dec(z_hat)
        loss,stat_loss = self.compute_loss(x, x_hat, z_mu, masks, device)
        ineq_defect = torch.sum(torch.abs(z_hat))/self.args.batch_size/self.args.z_n - self.args.sparse_level

        return cooper.CMPState(loss=loss+stat_loss, ineq_defect=ineq_defect, eq_defect=None)

